command:example.dev:code:
# Esporta e confronta con il backup precedente
$current = Export-ColorScriptMetadata -Path "./current-metadata.json" -IncludeFileInfo -PassThru
$previous = Get-Content "./previous-metadata.json" | ConvertFrom-Json
$new = $current | Where-Object { $_.Name -notin $previous.Name }
$removed = $previous | Where-Object { $_.Name -notin $current.Name }
Write-Host "Nuovi script: $($new.Count) | Script rimossi: $($removed.Count)"

dev:remarks.maml:para:
Recupera la directory della cache risolta. `Cache.Path` rimane l'override opzionale configurato dall'utente;
`Cache.EffectivePath` mostra la directory che il modulo utilizza effettivamente dopo le impostazioni predefinite della piattaforma e
vengono applicate le sostituzioni dell'ambiente.

command:example.dev:code:
$config = Get-ColorScriptConfiguration
if ($config.Startup.AutoShowOnImport) {
    Write-Host "Gli script di avvio sono abilitati"
}

$config = Get-ColorScriptConfiguration
if ($config.Cache.Path) {
    Write-Host "Percorso cache personalizzato configurato: $($config.Cache.Path)"
} else {
    Write-Host "Utilizzo del percorso cache predefinito"
}

Write-Host "Percorso cache effettivo: $($config.Cache.EffectivePath)"

# Crea cache per script filtrati
Get-ColorScriptList -Tag Recommended -AsObject |
    ForEach-Object {
        New-ColorScriptCache -Name $_.Name -PassThru
    } |
    Format-Table Name, Status

# Trova il primo script che corrisponde a un modello per una visualizzazione rapida
$script = Get-ColorScriptList -Name "aurora-*" -AsObject | Select-Object -First 1
if ($script) {
    Show-ColorScript -Name $script.Name -PassThru
}

# Verificare che tutti gli script di riferimento esistano prima di eseguire l'automazione
$requiredScripts = @("bars", "arch", "mandelbrot-zoom")
$available = Get-ColorScriptList -AsObject | Select-Object -ExpandProperty Name
$missing = $requiredScripts | Where-Object { $_ -notin $available }
if ($missing) {
    Write-Warning "Script mancanti: $($missing -join ', ')"
} else {
    Write-Host "Tutti gli script richiesti sono disponibili"
}

# Crea più colorscripts per un progetto
$scriptNames = @("company-logo", "team-banner", "status-display")
foreach ($name in $scriptNames) {
    New-ColorScript -Name $name -Category "Corporate" -Tag "Custom" -OutputPath ".\src" | Out-Null
}
Write-Host "Creati $($scriptNames.Count) modelli colorscript"

# Verificare le convenzioni sui nomi degli script
$validName = "123-start"
$invalidNames = @("-invalid", "_underscore-only", "contains space")
foreach ($name in $invalidNames) {
    try {
        New-ColorScript -Name $name -OutputPath ./temp -WhatIf -ErrorAction Stop
    } catch {
        Write-Warning "Nome non valido '$name': $_"
    }
}

# Crea con la convalida di categorie e tag
$categories = Get-ColorScriptList -AsObject | Select-Object -ExpandProperty Category -Unique
if ("Retro" -in $categories) {
    New-ColorScript -Name "retro-party" -OutputPath ./ColorScripts-Enhanced/Scripts -Category "Artistic" -Tag "Fun","Social"
} else {
    Write-Warning "Categoria Retro non trovata"
}

# Verificare che il ripristino abbia avuto esito positivo
$config = Reset-ColorScriptConfiguration -PassThru
if ($null -eq $config.Cache.Path -and $config.Cache.EffectivePath) {
    Write-Host "Configurazione ripristinata correttamente al valore predefinito della piattaforma"
} else {
    Write-Host "Configurazione ripristinata, ma è in uso un percorso personalizzato: $($config.Cache.Path)"
}

# Crea una presentazione di colorscripts geometrico
Get-ColorScriptList -Category Geometric -AsObject |
    ForEach-Object {
        Show-ColorScript -Name $_.Name
        Start-Sleep -Seconds 3
    }

# Esempio di gestione degli errori
try {
    Show-ColorScript -Name "nonexistent-script" -ErrorAction Stop
} catch {
    Write-Warning "Script non trovato: $_"
    Show-ColorScript  # Ritorno al casuale
}

# Costruisci l'integrazione dell'automazione
if ($env:CI) {
    Show-ColorScript -Name "Galaxy" -NoCache
} else {
    Show-ColorScript  # Visualizzazione casuale per uso interattivo
}

# Attività pianificata per il saluto del terminale
$scriptPath = "$(Get-Module ColorScripts-Enhanced).ModuleBase\Scripts\mandelbrot-zoom.ps1"
if (Test-Path $scriptPath) {
    & $scriptPath
} else {
    Show-ColorScript -Name mandelbrot-zoom
}
